public int compareTo(Magic o) {
    int diff = o.priority - priority;
    if (diff == 0) {
        diff = o.size() - size();
    }
    if (diff == 0) {
        diff = o.type.compareTo(type);
    }
    if (diff == 0) {
        diff = o.string.compareTo(string);
    }
    return diff;
}
